# Construct the input grid from the observed 5x5 framed-tile pattern, then add color bridges
# through only the zero-valued gutters between aligned equal-color tiles.
N=30
g=[[0]*N for _ in range(N)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3,0],[2,8,8,2,0],[3,2,2,3,0],[2,8,8,2,0],[0,0,0,0,0]]
for ri,r in enumerate(starts):
  for ci,c in enumerate(starts):
    if r+4>=N or c+4>=N: # edge partial tile follows the test's visible partial frame
      if r<N and c<N and (ri<4 or ci<4):
        # partial bottom/right tile: visible frame color 4 at row/column 29 as seen
        if ri==4 and ci<4:
          for x in range(c,c+5):
            if x<N:g[r][x]=4
        elif ci==4 and ri<4:
          for y in range(r,r+5):
            if y<N:g[y][c]=4
      continue
    if ri==4 or ci==4:
      continue
    for y in range(r,r+5):
      for x in range(c,c+5):
        g[y][x]=4
    k=colors[ri][ci]
    for y in range(r+1,r+4):
      for x in range(c+1,c+4):g[y][x]=k
# Draw horizontal bridges for aligned repeated color tiles, including across intervening tiles.
# Bridges only occupy the two-cell gutters; thickness follows the 3x3 colored core.
for rr in range(4):
  for a in range(4):
    for b in range(a+1,4):
      k=colors[rr][a]
      if k and k==colors[rr][b]:
        y0=starts[rr]+1
        for y in range(y0,y0+3):
          for t in range(a,b):
            for x in range(starts[t]+5, starts[t+1]):
              if g[y][x]==0:g[y][x]=k
# Vertical analogous
for cc in range(4):
  for a in range(4):
    for b in range(a+1,4):
      k=colors[a][cc]
      if k and k==colors[b][cc]:
        x0=starts[cc]+1
        for x in range(x0,x0+3):
          for t in range(a,b):
            for y in range(starts[t]+5, starts[t+1]):
              if g[y][x]==0:g[y][x]=k
print('{"action":"submit","grid":'+__import__('json').dumps(g,separators=(',',':'))+'}')

import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
core=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Reconstruct tiles and the clipped bottom/right edge exactly.
for i,r in enumerate(starts):
 for j,c in enumerate(starts):
  r1=min(r+5,n); c1=min(c+5,n)
  for y in range(r,r1):
   for x in range(c,c1):
    edge=(y==r or y==r+4 or x==c or x==c+4)
    if edge:g[y][x]=4
    elif i<4 and j<4:g[y][x]=core[i][j]
# Connect horizontally aligned matching non-background colored cores, painting only empty gutter cells.
for i in range(4):
 for a in range(4):
  for b in range(a+1,4):
   k=core[i][a]
   if k!=2 and core[i][b]==k:
    for y in range(starts[i]+1, starts[i]+4):
     for t in range(a,b):
      for x in range(starts[t]+5,starts[t+1]):
       if g[y][x]==0:g[y][x]=k
# Connect vertically aligned matching non-background cores.
for j in range(4):
 for a in range(4):
  for b in range(a+1,4):
   k=core[a][j]
   if k!=2 and core[b][j]==k:
    for x in range(starts[j]+1,starts[j]+4):
     for t in range(a,b):
      for y in range(starts[t]+5,starts[t+1]):
       if g[y][x]==0:g[y][x]=k
